package data_structures.linear;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class DoublyLinkedList {
public static class DoublyLinkedListNode<T>{public T value;public DoublyLinkedListNode<T> prev,next;public DoublyLinkedListNode(T v){value=v;}}public static class ListImpl<T> implements Iterable<T>{private DoublyLinkedListNode<T> head,tail;private int length;public static <T> ListImpl<T> from(Iterable<T> values){ListImpl<T> l=new ListImpl<>();for(T v:values)l.pushBack(v);return l;}public int size(){return length;}public T first(){return head==null?null:head.value;}public T last(){return tail==null?null:tail.value;}public DoublyLinkedListNode<T> pushBack(T v){DoublyLinkedListNode<T> n=new DoublyLinkedListNode<>(v);n.prev=tail;if(tail==null)head=n;else tail.next=n;tail=n;length++;return n;}public DoublyLinkedListNode<T> pushFront(T v){DoublyLinkedListNode<T> n=new DoublyLinkedListNode<>(v);n.next=head;if(head==null)tail=n;else head.prev=n;head=n;length++;return n;}public void unlink(DoublyLinkedListNode<T> n){if(n.prev==null)head=n.next;else n.prev.next=n.next;if(n.next==null)tail=n.prev;else n.next.prev=n.prev;n.next=n.prev=null;length--;}public T popBack(){if(tail==null)return null;T v=tail.value;unlink(tail);return v;}public T popFront(){if(head==null)return null;T v=head.value;unlink(head);return v;}public boolean remove(T v){for(DoublyLinkedListNode<T> n=head;n!=null;n=n.next)if(Objects.equals(n.value,v)){unlink(n);return true;}return false;}public List<T> toArray(){List<T> o=new ArrayList<>();for(T v:this)o.add(v);return o;}public Iterable<T> reversed(){List<T> o=new ArrayList<>();for(DoublyLinkedListNode<T> n=tail;n!=null;n=n.prev)o.add(n.value);return o;}public Iterator<T> iterator(){return new Iterator<>(){DoublyLinkedListNode<T> n=head;public boolean hasNext(){return n!=null;}public T next(){if(n==null)throw new NoSuchElementException();T v=n.value;n=n.next;return v;}};}}
}
